cd /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/p7rev_g4 && cat > doc.py <<'EOF'
import re,sys
def info(path):
    lines=open(path).read().split('\n'); d={}
    for i,l in enumerate(lines):
        m=re.match(r'^(?:private )?(theorem|def|abbrev|inductive|structure)\s+(\S+)',l)
        if m:
            j=i-1
            while j>=0 and lines[j].strip()=='' : j-=1
            has = lines[j].rstrip().endswith('-/') and not lines[j].lstrip().startswith('/-!')
            # find docstring text
            doc=''
            if has:
                k=j
                while k>=0 and '/--' not in lines[k]: k-=1
                if k>=0 and not any(lines[t].strip().startswith(('theorem','def','example')) for t in range(k+1,j)):
                    doc=' '.join(lines[k:j+1])
                else: has=False
            d[m.group(2)]=(i+1,has,doc)
    return d
a=info(sys.argv[1]); b=info(sys.argv[2])
for n,(ln,has,doc) in b.items():
    if n not in a: print('NEW',ln,n,'DOC' if has else 'NODOC', re.findall(r'\b(G[1-5]|[A-F]\d+|MM-03\.3[^ ,;)]*|§\d+)',doc)[:6])
    elif a[n][2]!=doc: print('DOCCHG',ln,n,'DOC' if has else 'NODOC', re.findall(r'\b(G[1-5]|[A-F]\d+|MM-03\.3[^ ,;)]*|§\d+)',doc)[:6])
EOF
python3 doc.py ../p7/mm03_p6.lean /Users/guygouri/Devlab/ernlang/ern/formal/Ern/MM03.lean

